using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;
using System.Diagnostics;
using System.Text.Json.Nodes;
namespace GpuPro.Windows;
public sealed partial class MainWindow {
 async Task BuildTuning(StackPanel host){try{var id=ActiveGpu.Id;var start=new ProcessStartInfo(Path.Combine(AppContext.BaseDirectory,"gpu-tuning-worker.exe")){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,StandardOutputEncoding=System.Text.Encoding.UTF8,RedirectStandardError=true};start.ArgumentList.Add("--id");start.ArgumentList.Add(id);using var p=Process.Start(start)??throw new IOException("Consulta de controles não iniciou.");var json=p.StandardOutput.ReadToEndAsync();await p.WaitForExitAsync();var controls=JsonNode.Parse(await json)?.AsObject()??throw new IOException("Controles não disponíveis.");
  if(controls.Count==0)host.Children.Add(Text("O driver não expôs controles de escrita reconhecidos para esta GPU neste Windows.",12));
  // Compacto: cada controle numa linha (controle deslizante, valor e botões) e dois controles por fileira.
  var grid=new Grid{ColumnSpacing=12,RowSpacing=12};grid.ColumnDefinitions.Add(new(){Width=new GridLength(1,GridUnitType.Star)});grid.ColumnDefinitions.Add(new(){Width=new GridLength(1,GridUnitType.Star)});int index=0;
  foreach(var control in controls){string domain=control.Key;var c=control.Value!.AsObject();var value=new NumberBox{Minimum=c["min"]!.GetValue<int>(),Maximum=c["max"]!.GetValue<int>(),Value=c["current"]!.GetValue<int>(),SmallChange=1,Width=110,SpinButtonPlacementMode=NumberBoxSpinButtonPlacementMode.Compact};var slider=new Slider{Minimum=value.Minimum,Maximum=value.Maximum,Value=value.Value,MinWidth=160,VerticalAlignment=VerticalAlignment.Center};slider.ValueChanged+=(s,e)=>value.Value=Math.Round(slider.Value);value.ValueChanged+=(s,e)=>slider.Value=value.Value;
   var line=new Grid{ColumnSpacing=8};line.ColumnDefinitions.Add(new(){Width=new GridLength(1,GridUnitType.Star)});var parts=new List<UIElement>{value,Button("Aplicar",async()=>await ApplyTuning(id,domain,(int)value.Value))};if(domain.StartsWith("fan"))parts.Add(Button("Automático",async()=>await ApplyTuning(id,domain,-1)));
   line.Children.Add(slider);for(int i=0;i<parts.Count;i++){line.ColumnDefinitions.Add(new(){Width=GridLength.Auto});Grid.SetColumn((FrameworkElement)parts[i],i+1);((FrameworkElement)parts[i]).VerticalAlignment=VerticalAlignment.Center;line.Children.Add(parts[i]);}
   if(grid.RowDefinitions.Count<=index/2)grid.RowDefinitions.Add(new(){Height=GridLength.Auto});var card=Tighten(Section(domain switch{"core"=>"Offset GPU · MHz","mem"=>"Offset memória · MHz","power"=>"Power limit · W",_=>"Ventoinha "+(int.TryParse(domain[3..],out var fan)?fan+1:1)+" · %"},line));Grid.SetRow(card,index/2);Grid.SetColumn(card,index%2);grid.Children.Add(card);index++;}
  host.Children.Add(grid);
  host.Children.Add(Text("Ajustes manuais somente nas faixas reconhecidas pelo driver; cada aplicação pede confirmação e autorização do Windows. Nada é aplicado ao abrir a página. Undervolt/tensão absoluta só aparece quando houver uma API Windows reconhecida.",11));}
  catch(Exception e){host.Children.Add(Text("Controles de ajuste indisponíveis para esta GPU. Detalhes em Notificações & Logs.",12));Record("Overclock: "+e.Message,true);}}
 async Task ApplyTuning(string id,string domain,int value){try{if(worker!=null||benchmark)throw new InvalidOperationException("Encerre o teste antes de ajustar a GPU.");if(id!=ActiveGpu.Id)throw new InvalidOperationException("A GPU selecionada mudou. Reabra a página.");var confirm=new ContentDialog{XamlRoot=Root.XamlRoot,Title="Confirmar ajuste manual",Content=$"GPU: {ActiveGpu.Name}\nControle: {domain}\nValor: {value}\nO ajuste pode causar instabilidade. Continuar?",PrimaryButtonText="Aplicar",CloseButtonText="Cancelar",DefaultButton=ContentDialogButton.Close};if(await confirm.ShowAsync()!=ContentDialogResult.Primary)return;gpuChoice.IsEnabled=false;var executable=Path.Combine(AppContext.BaseDirectory,"gpu-tuning-worker.exe");var args=$"--apply --id {id} --domain {domain} --value {value}";using var process=Process.Start(new ProcessStartInfo(executable,args){UseShellExecute=true,Verb="runas",WorkingDirectory=AppContext.BaseDirectory})??throw new IOException("Auxiliar não iniciou.");await process.WaitForExitAsync();Record(process.ExitCode==0?$"Ajuste {domain}={value} confirmado pelo driver · {ActiveGpu.Name}":$"Ajuste {domain}={value} não confirmado. Código: {process.ExitCode}",process.ExitCode!=0);await Poll();}catch(Exception e){TestError(e);}finally{gpuChoice.IsEnabled=true;}}
}
